import os
import boto3
from datetime import datetime

def write_correlated_logs(payload, config=None):
    config = config or {}
    # Using AWS CloudWatch Logs as the managed service
    client = boto3.client('logs', region_name=config.get('region', 'us-east-1'))

    # Generate or extract correlation ID
    correlation_id = config.get('correlation_id') or str(datetime.utcnow().timestamp())

    # Prepare log event with correlation identifier
    log_event = {
        'logGroupName': config.get('log_group', '/aws/lambda/my-function'),
        'logStreamName': config.get('log_stream', f"stream-{correlation_id}"),
        'logEvents': [
            {
                'timestamp': int(datetime.utcnow().timestamp() * 1000),
                'message': f'{{"correlation_id": "{correlation_id}", "payload": {str(payload)}}}'
            }
        ]
    }

    # Send log event to CloudWatch
    result = client.put_log_events(**log_event)
    return result
